USE master;
IF DB_ID('Oficina') IS NOT NULL
   DROP DATABASE Oficina;
CREATE DATABASE Oficina;
GO
USE Oficina;
CREATE TABLE Cliente (
  cli_codigo INT IDENTITY NOT NULL,
  nome VARCHAR(50) NOT NULL,
  PRIMARY KEY (cli_codigo)
);

CREATE TABLE Fabricante (
  fab_codigo CHAR(14) NOT NULL,
  nome VARCHAR(50) NOT NULL,
  PRIMARY KEY (fab_codigo)
);

CREATE TABLE Peca (
  pec_codigo INT IDENTITY NOT NULL,
  descricao VARCHAR(50) NOT NULL,
  preco DECIMAL(5,2) NOT NULL,
  PRIMARY KEY (pec_codigo)
);

CREATE TABLE Servico (
  ser_codigo INT IDENTITY NOT NULL,
  descricao VARCHAR(50) NOT NULL,
  preco DECIMAL(5,2) NOT NULL,
  PRIMARY KEY (ser_codigo)
);

CREATE TABLE PF (
  cli_cpf CHAR(11) NOT NULL,
  cliente_cli_codigo INT NOT NULL,
  nome VARCHAR(50) NOT NULL,
  sexo CHAR(1) NOT NULL CHECK (sexo IN ('M', 'F')),
  PRIMARY KEY (cli_cpf),
  FOREIGN KEY (cliente_cli_codigo) REFERENCES Cliente (cli_codigo)
);

CREATE TABLE PJ (
  cli_cnpj CHAR(14) NOT NULL,
  cliente_cli_codigo INT NOT NULL,
  razaosocial VARCHAR(50) NOT NULL,
  PRIMARY KEY (cli_cnpj),
  FOREIGN KEY (cliente_cli_codigo) REFERENCES Cliente (cli_codigo)
);

CREATE TABLE Modelo (
  mod_codigo INT IDENTITY NOT NULL,
  fabricante_fab_codigo CHAR(14) NOT NULL,
  descricao VARCHAR(50) NOT NULL,
  PRIMARY KEY (mod_codigo),
  FOREIGN KEY (fabricante_fab_codigo) REFERENCES Fabricante (fab_codigo)
);

CREATE TABLE Veiculo (
  vei_placa CHAR(7) NOT NULL,
  modelo_mod_codigo INT NOT NULL,
  cor VARCHAR(20) NOT NULL,
  PRIMARY KEY (vei_placa),
  FOREIGN KEY (modelo_mod_codigo) REFERENCES Modelo (mod_codigo)
);

CREATE TABLE OES (
  oes_numero INT IDENTITY NOT NULL,
  cliente_cli_codigo INT NOT NULL,
  veiculo_vei_placa CHAR(7) NOT NULL,
  descricao VARCHAR(50) NOT NULL,
  data DATE NOT NULL,
  PRIMARY KEY (oes_numero),
  FOREIGN KEY (cliente_cli_codigo) REFERENCES Cliente (cli_codigo),
  FOREIGN KEY (veiculo_vei_placa) REFERENCES Veiculo (vei_placa)
);

CREATE TABLE OES_Peca (
  peca_pec_codigo INT NOT NULL,
  oes_oes_numero INT NOT NULL,
  quantidade INT NOT NULL,
  preco DECIMAL(5,2) NOT NULL,
  PRIMARY KEY (peca_pec_codigo, oes_oes_numero),
  FOREIGN KEY (peca_pec_codigo) REFERENCES Peca (pec_codigo),
  FOREIGN KEY (oes_oes_numero) REFERENCES OES (oes_numero)
);

CREATE TABLE OES_Servico (
  servico_ser_codigo INT NOT NULL,
  oes_oes_numero INT NOT NULL,
  quantidade INT NOT NULL,
  preco DECIMAL(5,2) NOT NULL,
  PRIMARY KEY (servico_ser_codigo, oes_oes_numero),
  FOREIGN KEY (servico_ser_codigo) REFERENCES Servico (ser_codigo),
  FOREIGN KEY (oes_oes_numero) REFERENCES OES (oes_numero)
);
